 claim. Fixture original Store resolve_domain_items test uses actual synthetic original Start and unknown observation with explicit DTO conversion. No source DB reads.\\n\\n-- Docs: https://docs.pytest.org/en/stable/how-to/capture-warnings.html\\n558 passed, 7 warnings in 30.65s\"}}"}],"timestamp":1792066123843}}
{"type":"message_end","message":{"role":"user","content":[{"type":"text","text":"{\"schema\": \"aos-material-review/v1\", \"request_id\": \"qyh-customer-closure-bounded-reader-20261015-code-r1\", \"task_id\": \"qyh-customer-closure-bounded-reader-20261015\", \"owner\": \"codex-01a13484-f019-7d82-94ce-812396db9124\", \"kind\": \"quality\", \"baseline\": {\"head\": \"f3dd116e9c753e94af91667bf13da4f544938945\", \"authority_revision\": \"AOS-002038\", \"files\": {\".evidence/qyh-customer-closure-bounded-reader-20261015/code-review-material-r1.txt\": \"70fae6e5ffece0fdb6cee21af4e15c6984ef605eb5fd887fa908da2c4f78d362\"}}, \"claims\": [\"Customer independent reader reuses original shared codec/service, validates saved typed hash/ID/ledger/exact binding/source type and public Task string revision; preserves unknown quantity null, immature and request_more without current Start/Consent/Receipt authority. Creator/price code remains unchanged.\", \"Fixed four-table parameterized tenant/customer reads require verified readonly RR and one cutoff, SQL CASE 64KiB single payload and total/deadline bounds, strict raw roundtrip/outer/ref/privacy fail-closed errors. Only missing rows yield empty, commands empty and three effect booleans false.\", \"Current four-overlay frozen r3 records 558 passing tests and unchanged SHAs; owned disposable native PG records original DDL, true empty/nonempty, snapshot/creator/RLS/25006/SQLCASE and exact CID stopped. This supports saved-read candidate only, not deployment/business/eight-visual/full Goal completion; unsupplied native controller body is not claimed independently inspected.\"], \"materials\": {\".evidence/qyh-customer-closure-bounded-reader-20261015/code-review-material-r1.txt\": \"CUSTOMER SAVED CLOSURE READER CODE QUALITY, NOT DEPLOYED. Design r2 PASS legally consumed; first NEED and raw RED/failed test assertion revisions retained, never relabeled. Current frozen r3 558PASS. Full231Goal ACTIVE, no current Start/Consent/Receipt or operating authority. Shared creator/price code untouched.\\nFULL SOURCE services/aos-api/aos_api/ecommerce_customer_closure_readonly.py SHA 1400d88963b41492eb684603503c85181cf984c236433f1f355a2b5695808535\\n\\\"\\\"\\\"Bounded historical customer closure snapshots, never operating authority.\\\"\\\"\\\"\\nfrom time import monotonic\\nimport json\\n\\nimport psycopg\\nfrom psycopg import IsolationLevel\\n\\nfrom aos_api.db import connect_read_only\\nfrom aos_api.ecommerce_three_module_closure_readonly import (\\n    MAX_ITEM_BYTES, MAX_TOTAL_BYTES, _TABLES, _SavedBindings, _strict_price_raw,\\n    _time, _visible, CreatorClosureReadonlyError, CreatorClosureReadonlyReader,\\n)\\nfrom aos_api.ecommerce_workshop_three_module_closure import (\\n    EcommerceWorkshopThreeModuleClosureService, ThreeModule,\\n)\\n\\n\\nclass CustomerClosureReadonlyError(RuntimeError):\\n    def __init__(self, code):\\n        self.code = code\\n        super().__init__(code)\\n\\n\\ndef _deny(suffix):\\n    raise CustomerClosureReadonlyError('CUSTOMER_CLOSURE_READ_' + suffix)\\n\\n\\nclass CustomerClosureReadonlyReader:\\n    def __init__(self, *, connect_factory=None):\\n        self._connect = connect_factory or connect_read_only\\n\\n    @staticmethod\\n    def _row(conn, scope, kind, closure_id):\\n        table, _ = _TABLES[kind]\\n        identity = 'closure_id' if kind == 'closure' else 'binding_id'\\n        source = ('CASE WHEN length(source_id)<=240 THEN source_id ELSE NULL END AS source_id'\\n                  if kind == 'closure' else 'NULL AS source_id')\\n        predicate = 'module=%s' if kind == 'closure' else 'closure_id=%s'\\n        return conn.execute(\\n            f'''SELECT org_id,project_id,\\n                CASE WHEN length({identity})<=240 THEN {identity} ELSE NULL END AS resource_id,\\n                CASE WHEN length(closure_id)<=240 THEN closure_id ELSE NULL END AS closure_id,\\n                revision,module,{source},content_hash,created_at,\\n                octet_length(authority_data::text) AS payload_bytes,\\n                CASE WHEN octet_length(authority_data::text)<={MAX_ITEM_BYTES}\\n                     THEN authority_data ELSE NULL END AS authority_data\\n                FROM {table} WHERE org_id=%s AND project_id=%s AND {predicate}\\n                ORDER BY created_at DESC,{identity} LIMIT 1''',\\n            (*scope.key, 'customer' if kind == 'closure' else closure_id),\\n        ).fetchone()\\n\\n    @staticmethod\\n    def _decode(row, scope, kind, cutoff, closure):\\n        raw = row['authority_data']\\n        if type(raw) is not dict:\\n            _deny('AUTHORITY_DRIFT')\\n        _strict_price_raw(raw)\\n        item = CreatorClosureReadonlyReader._decode(\\n            row, scope, kind, cutoff, closure, ThreeModule.CUSTOMER)\\n        if item.model_dump(mode='json', by_alias=True) != raw:\\n            _deny('AUTHORITY_DRIFT')\\n        if kind == 'closure' and any(\\n                value.receipt_ref is not None and value.receipt_ref.resource_type != 'ActionReceipt'\\n                for value in item.items):\\n            _deny('CONTENT_UNSUPPORTED')\\n        visible = json.dumps(_visible(item.model_dump(mode='json', by_alias=True)), ensure_ascii=False).lower()\\n        if any(word in visible for word in ('mobile', 'openid', 'email', 'address', 'contactvalue', 'providerpayload')):\\n            _deny('CONTENT_UNSUPPORTED')\\n        return item\\n\\n    def read(self, scope):\\n        started = monotonic()\\n\\n        def deadline():\\n            if monotonic() - started > 10:\\n                _deny('LIMIT_EXCEEDED')\\n\\n        try:\\n            with self._connect(scope) as conn:\\n                if (conn.read_only is not True or conn.autocommit is not False\\n                        or conn.isolation_level != IsolationLevel.REPEATABLE_READ):\\n                    _deny('UNAVAILABLE')\\n                deadline()\\n                conn.execute(\\\"SET LOCAL statement_timeout='3000ms'\\\")\\n                conn.execute(\\\"SET LOCAL lock_timeout='500ms'\\\")\\n                cutoff = conn.execute('SELECT transaction_timestamp() AS cutoff').fetchone()['cutoff']\\n                if not _time(cutoff, cutoff):\\n                    _deny('AUTHORITY_DRIFT')\\n                bindings = dict(closure=None, usage=None, effect=None, handoff=None)\\n                total = 0\\n                for kind in _TABLES:\\n                    deadline()\\n                    closure = bindings['closure']\\n                    if kind != 'closure' and closure is None:\\n                        break\\n                    row = self._row(conn, scope, kind, getattr(closure, 'closure_id', None))\\n                    if row is None:\\n                        continue\\n                    size = row['payload_bytes']\\n                    if type(size) is not int or size < 1:\\n                        _deny('AUTHORITY_DRIFT')\\n                    total += size\\n                    if size > MAX_ITEM_BYTES or total > MAX_TOTAL_BYTES:\\n                        _deny('LIMIT_EXCEEDED')\\n                    bindings[kind] = self._decode(row, scope, kind, cutoff, closure)\\n                    deadline()\\n                view = EcommerceWorkshopThreeModuleClosureService(_SavedBindings(bindings)).contribution_view(\\n                    scope, ThreeModule.CUSTOMER, now=cutoff)\\n                data = view.model_dump(mode='json', by_alias=True)\\n                data.update(allowedCommands=[], handoffConsumeAllowed=False,\\n                            memoryPromotionAllowed=False, externalEffectsAllowed=False)\\n                result = type(view).model_validate(data)\\n                if len(result.model_dump_json(by_alias=True).encode()) > MAX_TOTAL_BYTES:\\n                    _deny('LIMIT_EXCEEDED')\\n                deadline()\\n                return result\\n        except CustomerClosureReadonlyError:\\n            raise\\n        except CreatorClosureReadonlyError as exc:\\n            raise CustomerClosureReadonlyError(\\n                exc.code.replace('CREATOR_CLOSURE_READ_', 'CUSTOMER_CLOSURE_READ_', 1)) from exc\\n        except RecursionError:\\n            _deny('LIMIT_EXCEEDED')\\n        except psycopg.Error:\\n            _deny('UNAVAILABLE')\\n        except (ValueError, KeyError, TypeError, AttributeError, OverflowError):\\n            _deny('AUTHORITY_DRIFT')\\n\\nFULL SOURCE services/aos-api/tests/test_ecommerce_customer_closure_readonly.py SHA 2102354dc66e2cc1cbff7166297b5d0f24eab387cf79068b1bc5033d276b3f3b\\n\\\"\\\"\\\"Customer saved closure contract; synthetic authority is never live approval.\\\"\\\"\\\"\\nfrom datetime import timedelta\\nimport json\\n\\nimport psycopg\\nimport pytest\\nfrom psycopg import IsolationLevel\\n\\nfrom aos_api.ecommerce_workshop_three_module_closure import (\\n    BindThreeModuleEffectRequest, BindThreeModuleHandoffRequest,\\n    BindThreeModuleUsageRequest, CompileThreeModuleClosureRequest,\\n    EcommerceWorkshopThreeModuleClosureService,\\n)\\nfrom tests.test_ecommerce_three_module_closure_readonly import (\\n    SCOPE, NOW, CUTOFF, TABLES, ProducerFixture, Connection, Cursor, ref,\\n)\\n\\n\\ndef customer_rows(scope=SCOPE):\\n    producer = ProducerFixture()\\n    service = EcommerceWorkshopThreeModuleClosureService(producer)\\n    closure = service.compile(scope, CompileThreeModuleClosureRequest(\\n        module='customer', sourceRef=ref('CustomerBatchStartDecisionRevision', 'customer-fixture')),\\n        'fixture-actor', now=NOW)\\n    exact = service._ref('ThreeModuleClosureRevision', closure.closure_id, closure.content_hash)\\n    values = dict(closure=closure,\\n        usage=service.bind_usage(scope, BindThreeModuleUsageRequest(closureRef=exact, usageReceiptId='fixture-usage'), now=NOW),\\n        effect=service.bind_effect(scope, BindThreeModuleEffectRequest(closureRef=exact, effectReviewId='fixture-effect'), now=NOW),\\n        handoff=service.bind_handoff(scope, BindThreeModuleHandoffRequest(closureRef=exact, handoffId='fixture-handoff'), now=NOW))\\n    rows = {}\\n    for kind, value in values.items():\\n        raw = value.model_dump(mode='json', by_alias=True)\\n        rows[kind] = dict(org_id=scope.org_id, project_id=scope.project_id,\\n            resource_id=closure.closure_id if kind == 'closure' else value.binding_id,\\n            closure_id=closure.closure_id, revision=1, module='customer' if kind == 'closure' else None,\\n            source_id=closure.source_ref.resource_id if kind == 'closure' else None,\\n            content_hash=value.content_hash, created_at=NOW,\\n            payload_bytes=len(json.dumps(raw).encode()), authority_data=raw)\\n    return rows\\n\\n\\nclass CustomerConnection(Connection):\\n    def execute(self, sql, params=None):\\n        if sql.startswith('SET LOCAL'):\\n            assert sql in (\\\"SET LOCAL statement_timeout='3000ms'\\\", \\\"SET LOCAL lock_timeout='500ms'\\\")\\n            self.queries.append((sql, params)); return Cursor(None)\\n        if 'FROM ecommerce_three_module_closure_revision ' in sql:\\n            assert params == (*self.scope.key, 'customer')\\n        return super().execute(sql, params)\\n\\n\\ndef reader(conn):\\n    from aos_api.ecommerce_customer_closure_readonly import CustomerClosureReadonlyReader\\n    return CustomerClosureReadonlyReader(connect_factory=lambda scope: conn)\\n\\n\\ndef denied(conn):\\n    from aos_api.ecommerce_customer_closure_readonly import CustomerClosureReadonlyError\\n    with pytest.raises(CustomerClosureReadonlyError) as caught:\\n        reader(conn).read(SCOPE)\\n    assert caught.value.code.startswith('CUSTOMER_CLOSURE_READ_')\\n    return caught.value.code\\n\\n\\ndef test_empty_is_true_missing_history_and_no_commands():\\n    conn = CustomerConnection({}); value = reader(conn).read(SCOPE)\\n    assert value.latest_closure is value.latest_usage is value.latest_effect is value.latest_handoff is None\\n    assert len(value.blockers) == 4 and value.evaluated_at == CUTOFF\\n    assert value.allowed_commands == [] and not value.handoff_consume_allowed\\n    assert not value.memory_promotion_allowed and not value.external_effects_allowed\\n    assert len([s for s, _ in conn.queries if s.startswith('SELECT')]) == 2\\n\\n\\ndef test_actual_original_producer_hashes_preserve_five_independent_axes():\\n    conn = CustomerConnection(customer_rows()); value = reader(conn).read(SCOPE)\\n    assert value.module.value == 'customer' and value.primary_colleague == '私域管家'\\n    assert value.latest_closure.source_ref.resource_type == 'CustomerBatchStartDecisionRevision'\\n    assert value.latest_closure.ledger.unknown == 1 and value.latest_closure.ledger.state.value == 'partial'\\n    assert value.latest_usage.quantity is None and value.latest_usage.quality == 'unknown'\\n    assert value.latest_effect.accepted and not value.latest_effect.effect_completed\\n    assert value.latest_effect.cutoff_at > CUTOFF\\n    assert value.latest_handoff.business_decision == 'request_more'\\n    assert value.latest_handoff.task_ref['revision'] == '1'\\n    assert value.allowed_commands == [] and not value.external_effects_allowed\\n    selects = [s for s, _ in conn.queries if s.startswith('SELECT')]\\n    assert len(selects) == 5\\n    assert all('CASE WHEN' in s and 'octet_length' in s and 'LIMIT 1' in s for s in selects[1:])\\n\\n\\n@pytest.mark.parametrize('kind', list(TABLES))\\n@pytest.mark.parametrize('field,value', [('org_id', 'foreign'), ('project_id', 'foreign'),\\n    ('revision', True), ('resource_id', 'foreign'), ('content_hash', 'b' * 64),\\n    ('module', 'price'), ('created_at', CUTOFF + timedelta(seconds=1))])\\ndef test_each_outer_authority_is_checked(kind, field, value):\\n    rows = customer_rows(); rows[kind][field] = value\\n    assert denied(CustomerConnection(rows)).endswith('AUTHORITY_DRIFT')\\n\\n\\n@pytest.mark.parametrize('kind', list(TABLES))\\ndef test_single_payload_limit_before_decode(kind):\\n    rows = customer_rows(); rows[kind].update(payload_bytes=65537, authority_data=None)\\n    assert denied(CustomerConnection(rows)).endswith('LIMIT_EXCEEDED')\\n\\n\\n@pytest.mark.parametrize('kind,field,value', [('closure', 'revision', 1.0),\\n    ('effect', 'sampleCount', True), ('effect', 'minSample', 10.0),\\n    ('effect', 'accepted', 1), ('handoff', 'disclosureRefCount', False),\\n    ('usage', 'adjustmentTotal', float('inf')), ('usage', 'quantity', float('nan'))])\\ndef test_coercion_or_nonfinite_never_fabricates_canonical_evidence(kind, field, value):\\n    rows = customer_rows(); rows[kind]['authority_data'][field] = value\\n    denied(CustomerConnection(rows))\\n\\n\\n@pytest.mark.parametrize('kind', list(TABLES))\\ndef test_nested_tenant_and_unknown_field_fail(kind):\\n    rows = customer_rows(); rows[kind]['authority_data']['tenant']['projectId'] = 'foreign'\\n    denied(CustomerConnection(rows))\\n    rows = customer_rows(); rows[kind]['authority_data']['unrecognized'] = 'not canonical'\\n    denied(CustomerConnection(rows))\\n\\n\\n@pytest.mark.parametrize('kind', ['usage', 'effect', 'handoff'])\\ndef test_exact_binding_never_borrows_other_closure(kind):\\n    rows = customer_rows(); rows[kind]['authority_data']['closureRef']['contentHash'] = 'sha256:' + 'b' * 64\\n    denied(CustomerConnection(rows))\\n\\n\\n@pytest.mark.parametrize('field,value', [('read_only', False), ('autocommit', True),\\n    ('isolation_level', IsolationLevel.READ_COMMITTED)])\\ndef test_transaction_required_before_sql(field, value):\\n    conn = CustomerConnection({}); setattr(conn, field, value)\\n    assert denied(conn).endswith('UNAVAILABLE') and not conn.queries\\n\\n\\ndef test_db_exception_is_not_empty_or_leaked():\\n    conn = CustomerConnection({})\\n    def fail(*args): raise psycopg.OperationalError('private credential detail')\\n    conn.execute = fail\\n    assert denied(conn) == 'CUSTOMER_CLOSURE_READ_UNAVAILABLE'\\n\\n\\n@pytest.mark.parametrize('actor', ['13800138000', 'operator@example.invalid', 'providerPayload-in-actor'])\\ndef test_private_free_text_never_reaches_public_output(actor):\\n    rows = customer_rows(); rows['closure']['authority_data']['compiledBy'] = actor\\n    assert denied(CustomerConnection(rows)).split('_')[-1] in {'UNAVAILABLE', 'UNSUPPORTED'}\\n\\n\\ndef test_deep_driver_json_fails_limit_not_unhandled_error():\\n    conn = CustomerConnection({})\\n    def fail(*args): return json.loads('[' * 1100 + '0' + ']' * 1100)\\n    conn.execute = fail\\n    assert denied(conn) == 'CUSTOMER_CLOSURE_READ_LIMIT_EXCEEDED'\\n\\n\\ndef test_deadline_is_bounded(monkeypatch):\\n    from aos_api import ecommerce_customer_closure_readonly as module\\n    ticks = iter([0, 11]); monkeypatch.setattr(module, 'monotonic', lambda: next(ticks))\\n    assert denied(CustomerConnection({})).endswith('LIMIT_EXCEEDED')\\n\\n\\ndef test_original_customer_start_observation_and_store_status_mapping(monkeypatch):\\n    from tests.aip import test_w6_08_customer_contact as fixture\\n    from aos_api import ecommerce_workshop_customer_contact as contact\\n    from aos_api.ecommerce_workshop_three_module_closure import ThreeModule\\n    from aos_api.ecommerce_workshop_three_module_closure_store import EcommerceWorkshopThreeModuleClosureStore\\n    monkeypatch.setattr(fixture, 'SCOPE', SCOPE)\\n    service, store, batch = fixture.service_fixture()\\n    service.create_frequency_policy(SCOPE, fixture.CreateCustomerFrequencyPolicyRequest(\\n        policyId='frequency-policy', revision=1, channel='wecom', purpose='retention', timezone='Asia/Shanghai',\\n        quietHoursStart='22:00', quietHoursEnd='08:00', rollingWindowHours=168, maximumContacts=2), 'fixture-actor', now=fixture.NOW)\\n    started = service.start_batch(SCOPE, batch.batch_id, fixture.start_request(batch), 'fixture-actor', now=fixture.NOW)\\n    exact = fixture.full_ref('CustomerBatchStartDecisionRevision', started.decision_id, started.content_hash)\\n    receipt = fixture.ref('ActionReceipt', 'fixture-receipt', 'f')\\n    store.receipts[(*SCOPE.key, receipt.resource_id)] = (receipt.content_hash, started.items[0].binding_hash)\\n    observation = service.record_dispatch_observation(SCOPE, fixture.RecordCustomerDispatchObservationRequest(\\n        startDecisionRef=exact, itemKey=started.items[0].item_key, actionReceiptRef=receipt,\\n        state='unknown', observedAt=fixture.NOW + timedelta(seconds=1)))\\n    class SourceCursor:\\n        def __init__(self, rows): self.rows = rows\\n        def fetchone(self): return self.rows[0]\\n        def fetchall(self): return self.rows\\n    class SourceConnection:\\n        def __enter__(self): return self\\n        def __exit__(self, *args): return False\\n        def execute(self, sql, params):\\n            assert sql.startswith('SELECT') and params[:2] == SCOPE.key\\n            if 'FROM ecommerce_customer_batch_start_decision_revision ' in sql:\\n                return SourceCursor([dict(authority_data=contact.customer_start_authority_data(started), content_hash=started.content_hash)])\\n            assert 'FROM ecommerce_customer_dispatch_observation ' in sql\\n            return SourceCursor([dict(authority_data=observation.model_dump(mode='json', by_alias=True))])\\n    original = EcommerceWorkshopThreeModuleClosureStore(read_connect_factory=lambda scope: SourceConnection())\\n    items = original.resolve_domain_items(SCOPE, ThreeModule.CUSTOMER, exact)\\n    assert len(items) == 1 and items[0].original_status == 'unknown'\\n    assert items[0].canonical_outcome.value == 'unknown'\\n    assert items[0].receipt_ref.model_dump(mode='json', by_alias=True) == receipt.model_dump(mode='json', by_alias=True)\\n    original.resolve_domain_items = lambda *args: items\\n    original.append_closure = lambda scope, value: value\\n    closure = EcommerceWorkshopThreeModuleClosureService(original).compile(SCOPE,\\n        CompileThreeModuleClosureRequest(module='customer', sourceRef=exact.model_dump(mode='json', by_alias=True)),\\n        'fixture-actor', now=NOW)\\n    assert closure.ledger.unknown == 1 and closure.ledger.succeeded == 0\\n\\nFULL SOURCE services/aos-api/aos_api/ecommerce_three_module_closure_readonly.py SHA 1083725c55b95bd755a74a64416cb1896a463c095992bc1154261af3ea41adcb\\n\\\"\\\"\\\"Bounded saved closure evidence, never compile/bind/consume authority.\\\"\\\"\\\"\\nfrom datetime import datetime\\nimport json\\nimport math\\nfrom time import monotonic\\n\\nimport psycopg\\nfrom psycopg import IsolationLevel\\n\\nfrom aos_api.aip_contracts import HandoffResourceRef, ResourceRef\\nfrom aos_api.db import connect_read_only\\nfrom aos_api.ecommerce_workshop_three_module_closure import (\\n    CompileThreeModuleClosureRequest, EcommerceWorkshopThreeModuleClosureService,\\n    ThreeModule, ThreeModuleClosureRevision, ThreeModuleEffectBindingRevision,\\n    ThreeModuleHandoffBindingRevision, ThreeModuleUsageBindingRevision,\\n    _ledger, canonical_hash,\\n)\\nfrom aos_api.ecommerce_workshop_three_module_closure_store import _STATUS\\nfrom aos_api.public_contracts import redact_sensitive\\n\\nMAX_ITEM_BYTES = 64 * 1024\\nMAX_TOTAL_BYTES = 1024 * 1024\\n_TABLES = {\\n    'closure': ('ecommerce_three_module_closure_revision', ThreeModuleClosureRevision),\\n    'usage': ('ecommerce_three_module_usage_binding_revision', ThreeModuleUsageBindingRevision),\\n    'effect': ('ecommerce_three_module_effect_binding_revision', ThreeModuleEffectBindingRevision),\\n    'handoff': ('ecommerce_three_module_handoff_binding_revision', ThreeModuleHandoffBindingRevision),\\n}\\n\\n\\nclass CreatorClosureReadonlyError(RuntimeError):\\n    def __init__(self, code):\\n        self.code = code\\n        super().__init__(code)\\n\\n\\nclass PriceClosureReadonlyError(CreatorClosureReadonlyError):\\n    \\\"\\\"\\\"Stable price-specific boundary around the shared saved-record codec.\\\"\\\"\\\"\\n\\n\\ndef _deny(suffix):\\n    raise CreatorClosureReadonlyError('CREATOR_CLOSURE_READ_' + suffix)\\n\\n\\ndef _time(value, cutoff):\\n    return isinstance(value, datetime) and value.utcoffset() is not None and value <= cutoff\\n\\n\\ndef _ref_revision(raw):\\n    if type(raw) is not dict or type(raw.get('revision')) is not int or raw['revision'] < 1:\\n        _deny('AUTHORITY_DRIFT')\\n\\n\\ndef _strict_price_raw(value):\\n    integers = {'revision', 'total', 'inProgress', 'succeeded', 'failed', 'unknown',\\n                'disputed', 'skipped', 'sampleCount', 'minSample', 'disclosureRefCount'}\\n    if isinstance(value, dict):\\n        for key, child in value.items():\\n            # Task/TaskRun use the public ResourceRef contract with a STRING\\n            # revision; the existing typed handoff validator checks them below.\\n            if key in {'taskRef', 'taskRunRef'}: continue\\n            if key in integers and type(child) is not int: _deny('AUTHORITY_DRIFT')\\n            if key in {'accepted', 'effectCompleted'} and type(child) is not bool: _deny('AUTHORITY_DRIFT')\\n            if key in {'quantity', 'adjustmentTotal'} and child is not None:\\n                if type(child) not in (int, float) or not math.isfinite(child): _deny('AUTHORITY_DRIFT')\\n            _strict_price_raw(child)\\n    elif isinstance(value, list):\\n        for child in value: _strict_price_raw(child)\\n\\n\\ndef _visible(value):\\n    # Typed hashes and derived identities are checked separately; hash digits are\\n    # not contact numbers. Every other public string retains the existing guard.\\n    if isinstance(value, dict):\\n        return {key: _visible(child) for key, child in value.items()\\n                if key not in {'contentHash', 'closureId', 'bindingId'}}\\n    if isinstance(value, list):\\n        return [_visible(child) for child in value]\\n    return value\\n\\n\\nclass _SavedBindings:\\n    def __init__(self, bindings): self.bindings = bindings\\n    def latest_bindings(self, scope, module): return self.bindings\\n\\n\\nclass CreatorClosureReadonlyReader:\\n    _module = ThreeModule.CREATOR\\n\\n    def __init__(self, *, connect_factory=None):\\n        self._connect = connect_factory or connect_read_only\\n\\n    @staticmethod\\n    def _row(conn, scope, kind, closure_id=None, module=ThreeModule.CREATOR):\\n        table, _ = _TABLES[kind]\\n        identity = 'closure_id' if kind == 'closure' else 'binding_id'\\n        source = 'source_id' if kind == 'closure' else 'NULL AS source_id'\\n        resource = f'{identity} AS resource_id'\\n        closure_column = 'closure_id'\\n        if module is ThreeModule.PRICE:\\n            resource = f'CASE WHEN length({identity})<=240 THEN {identity} ELSE NULL END AS resource_id'\\n            closure_column = 'CASE WHEN length(closure_id)<=240 THEN closure_id ELSE NULL END AS closure_id'\\n            if kind == 'closure': source = 'CASE WHEN length(source_id)<=240 THEN source_id ELSE NULL END AS source_id'\\n        predicate = 'module=%s' if kind == 'closure' else 'closure_id=%s'\\n        return conn.execute(\\n            f'''SELECT org_id,project_id,{resource},{closure_column},\\n                revision,module,{source},content_hash,created_at,\\n                octet_length(authority_data::text) AS payload_bytes,\\n                CASE WHEN octet_length(authority_data::text)<={MAX_ITEM_BYTES}\\n                     THEN authority_data ELSE NULL END AS authority_data\\n                FROM {table} WHERE org_id=%s AND project_id=%s AND {predicate}\\n                ORDER BY created_at DESC,{identity} LIMIT 1''',\\n            (*scope.key, module.value if kind == 'closure' else closure_id),\\n        ).fetchone()\\n\\n    @staticmethod\\n    def _decode(row, scope, kind, cutoff, closure=None, module=ThreeModule.CREATOR):\\n        if (row['org_id'], row['project_id']) != scope.key:\\n            _deny('AUTHORITY_DRIFT')\\n        if (type(row['revision']) is not int or row['revision'] != 1\\n                or not _time(row['created_at'], cutoff)):\\n            _deny('AUTHORITY_DRIFT')\\n        raw = row['authority_data']\\n        if type(raw) is not dict or type(raw.get('revision')) is not int or raw['revision'] != 1:\\n            _deny('AUTHORITY_DRIFT')\\n        model = _TABLES[kind][1]\\n        if module is ThreeModule.PRICE: _strict_price_raw(raw)\\n        item = model.model_validate(raw)\\n        if module is ThreeModule.PRICE and item.model_dump(mode='json', by_alias=True) != raw:\\n            _deny('AUTHORITY_DRIFT')\\n        if (item.tenant.org_id, item.tenant.project_id) != scope.key:\\n            _deny('AUTHORITY_DRIFT')\\n        if item.content_hash != row['content_hash']:\\n            _deny('AUTHORITY_DRIFT')\\n        if kind == 'closure':\\n            _ref_revision(raw['sourceRef'])\\n            CompileThreeModuleClosureRequest(module=module, sourceRef=item.source_ref)\\n            identity = 'three-module-closure-' + canonical_hash(\\n                [*scope.key, module, item.source_ref.resource_id])[:24]\\n            if (item.module is not module or row['module'] != module.value\\n                    or row['resource_id'] != identity or item.closure_id != identity\\n                    or row['closure_id'] != identity or row['source_id'] != item.source_ref.resource_id\\n                    or item.compiled_at != row['created_at'] or not _time(item.compiled_at, cutoff)\\n                    or item.ledger != _ledger(item.items)):\\n                _deny('AUTHORITY_DRIFT')\\n            keys = set()\\n            for original, source in zip(item.items, raw['items'], strict=True):\\n                _ref_revision(source['originalRef'])\\n                if source.get('receiptRef') is not None: _ref_revision(source['receiptRef'])\\n                expected = item.source_ref.model_copy(update={\\n                    'resource_id': item.source_ref.resource_id + ':' + original.item_key})\\n                if (original.item_key in keys or original.original_ref != expected\\n                        or _STATUS.get(original.original_status) != original.canonical_outcome):\\n                    _deny('AUTHORITY_DRIFT')\\n                keys.add(original.item_key)\\n            payload = dict(module=item.module, sourceRef=item.source_ref, items=item.items)\\n        else:\\n            _ref_revision(raw['closureRef'])\\n            exact = EcommerceWorkshopThreeModuleClosureService._ref(\\n                'ThreeModuleClosureRevision', closure.closure_id, closure.content_hash)\\n            if (row['module'] not in (None, module.value) or row['closure_id'] != closure.closure_id\\n                    or item.closure_ref != exact or item.bound_at != row['created_at']\\n                    or not _time(item.bound_at, cutoff) or item.bound_at < closure.compiled_at):\\n                _deny('AUTHORITY_DRIFT')\\n            payload = {'closureRef': item.closure_ref}\\n            if kind == 'usage':\\n                _ref_revision(raw['usageReceiptRef'])\\n                if item.usage_receipt_ref.resource_type != 'UsageReceipt': _deny('AUTHORITY_DRIFT')\\n                if module is ThreeModule.PRICE and item.settlement != item.quality: _deny('AUTHORITY_DRIFT')\\n                payload.update(usageReceiptRef=item.usage_receipt_ref, lineageId=item.lineage_id,\\n                               quality=item.quality, quantity=item.quantity, unit=item.unit,\\n                               adjustmentTotal=item.adjustment_total, settlement=item.settlement)\\n            elif kind == 'effect':\\n                _ref_revision(raw['effectReviewRef'])\\n                if item.effect_review_ref.resource_type != 'EffectReviewRevision': _deny('AUTHORITY_DRIFT')\\n                if (not _time(item.observed_at, item.bound_at)\\n                        or item.cutoff_at.utcoffset() is None\\n                        or (item.maturity_status == 'mature' and item.cutoff_at > item.observed_at)\\n                        or type(raw['accepted']) is not bool or type(raw['effectCompleted']) is not bool):\\n                    _deny('AUTHORITY_DRIFT')\\n                payload.update(effectReviewRef=item.effect_review_ref, maturityStatus=item.maturity_status,\\n                               accepted=item.accepted, effectCompleted=item.effect_completed,\\n                               sampleCount=item.sample_count, minSample=item.min_sample,\\n                               cutoffAt=item.cutoff_at, observedAt=item.observed_at)\\n            else:\\n                _ref_revision(raw['handoffRef'])\\n                if item.handoff_ref.resource_type != 'HandoffEnvelope': _deny('AUTHORITY_DRIFT')\\n                for value, expected_type in [(item.task_ref, 'Task'), (item.task_run_ref, 'TaskRun')]:\\n                    ref_model = HandoffResourceRef if 'contentHash' in value else ResourceRef\\n                    public_ref = ref_model.model_validate(value)\\n                    if public_ref.resource_type != expected_type:\\n                        _deny('CONTENT_UNSUPPORTED')\\n                payload.update(handoffRef=item.handoff_ref, transportStatus=item.transport_status,\\n                               businessDecision=item.business_decision, taskRef=item.task_ref,\\n                               taskRunRef=item.task_run_ref, disclosureRefCount=item.disclosure_ref_count)\\n            identity = 'three-module-' + kind + '-' + canonical_hash(payload)[:24]\\n            if row['resource_id'] != identity or item.binding_id != identity:\\n                _deny('AUTHORITY_DRIFT')\\n        if canonical_hash(payload) != item.content_hash:\\n            _deny('AUTHORITY_DRIFT')\\n        visible = _visible(item.model_dump(mode='json', by_alias=True))\\n        if redact_sensitive(visible) != visible:\\n            _deny('PRIVACY_UNAVAILABLE')\\n        if module is ThreeModule.PRICE:\\n            serialized = json.dumps(visible, ensure_ascii=False).lower()\\n            if any(word in serialized for word in ('mobile', 'openid', 'email', 'address', 'contactvalue', 'providerpayload')):\\n                _deny('CONTENT_UNSUPPORTED')\\n        return item\\n\\n    def read(self, scope):\\n        started = monotonic()\\n        def deadline():\\n            if self._module is ThreeModule.PRICE and monotonic() - started > 10: _deny('LIMIT_EXCEEDED')\\n        try:\\n            if self._module not in (ThreeModule.CREATOR, ThreeModule.PRICE): _deny('CONTENT_UNSUPPORTED')\\n            with self._connect(scope) as conn:\\n                if (conn.read_only is not True or conn.autocommit is not False\\n                        or conn.isolation_level != IsolationLevel.REPEATABLE_READ):\\n                    _deny('UNAVAILABLE')\\n                if self._module is ThreeModule.PRICE:\\n                    conn.execute(\\\"SET LOCAL statement_timeout='3000ms'\\\")\\n                    conn.execute(\\\"SET LOCAL lock_timeout='500ms'\\\")\\n                cutoff = conn.execute('SELECT transaction_timestamp() AS cutoff').fetchone()['cutoff']\\n                if not _time(cutoff, cutoff): _deny('AUTHORITY_DRIFT')\\n                bindings, total = dict(closure=None, usage=None, effect=None, handoff=None), 0\\n                for kind in _TABLES:\\n                    deadline()\\n                    if kind != 'closure' and bindings['closure'] is None: break\\n                    row = self._row(conn, scope, kind, getattr(bindings['closure'], 'closure_id', None), self._module)\\n                    if row is None: continue\\n                    size = row['payload_bytes']\\n                    if type(size) is not int or size < 1: _deny('AUTHORITY_DRIFT')\\n                    total += size\\n                    if size > MAX_ITEM_BYTES or total > MAX_TOTAL_BYTES: _deny('LIMIT_EXCEEDED')\\n                    bindings[kind] = self._decode(row, scope, kind, cutoff, bindings['closure'], self._module)\\n                view = EcommerceWorkshopThreeModuleClosureService(_SavedBindings(bindings)).contribution_view(\\n                    scope, self._module, now=cutoff)\\n                # Revalidate a complete public DTO; no validation-bypassing copy.\\n                data = view.model_dump(mode='json', by_alias=True)\\n                data.update(allowedCommands=[], handoffConsumeAllowed=False,\\n                            memoryPromotionAllowed=False, externalEffectsAllowed=False)\\n                result = type(view).model_validate(data)\\n                if len(result.model_dump_json(by_alias=True).encode()) > MAX_TOTAL_BYTES:\\n                    _deny('LIMIT_EXCEEDED')\\n                deadline()\\n                return result\\n        except CreatorClosureReadonlyError:\\n            raise\\n        except psycopg.Error:\\n            _deny('UNAVAILABLE')\\n        except (ValueError, KeyError, TypeError, AttributeError, OverflowError):\\n            _deny('AUTHORITY_DRIFT')\\n\\n\\nclass PriceClosureReadonlyReader(CreatorClosureReadonlyReader):\\n    _module = ThreeModule.PRICE\\n\\n    def read(self, scope):\\n        try:\\n            return super().read(scope)\\n        except CreatorClosureReadonlyError as exc:\\n            raise PriceClosureReadonlyError(exc.code.replace('CREATOR_CLOSURE_READ_', 'PRICE_CLOSURE_READ_', 1)) from exc\\n\\nFULL SOURCE services/aos-api/aos_api/ecommerce_workshop_three_module_closure.py SHA abb7798aae5fe3ca87ec0a05e2445bdbbf16cb54663009709bff20252458ea40\\n\\\"\\\"\\\"W6-09 canonical closure bridge for creator, price and customer modules.\\n\\nThe bridge never accepts caller-declared aggregate success.  Item outcomes,\\nusage, effect maturity and handoff decisions are resolved from their existing\\ntenant authorities and remain five independent axes.\\n\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport hashlib\\nimport json\\nfrom datetime import UTC, datetime\\nfrom enum import StrEnum\\nfrom typing import Any\\n\\nfrom pydantic import Field, model_validator\\n\\nfrom aos_api.aip_contracts import AipContractModel, TenantContext\\nfrom aos_api.tenant_scope import TenantScope\\n\\n\\nTHREE_MODULE_CLOSURE_SCHEMA_VERSION = \\\"aos.ecommerce-workshop.three-module-closure/v1\\\"\\n\\n\\ndef canonical_hash(value: Any) -> str:\\n    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(\\\",\\\", \\\":\\\"), default=str)\\n    return hashlib.sha256(payload.encode()).hexdigest()\\n\\n\\nclass ThreeModuleClosureBlocked(RuntimeError):\\n    code = \\\"THREE_MODULE_CLOSURE_BLOCKED\\\"\\n\\n\\nclass ThreeModuleClosureConflict(ThreeModuleClosureBlocked):\\n    code = \\\"THREE_MODULE_CLOSURE_CONFLICT\\\"\\n\\n\\nclass ThreeModule(StrEnum):\\n    CREATOR = \\\"creator\\\"\\n    PRICE = \\\"price\\\"\\n    CUSTOMER = \\\"customer\\\"\\n\\n\\nclass CanonicalItemOutcome(StrEnum):\\n    IN_PROGRESS = \\\"in_progress\\\"\\n    SUCCEEDED = \\\"succeeded\\\"\\n    FAILED = \\\"failed\\\"\\n    UNKNOWN = \\\"unknown\\\"\\n    DISPUTED = \\\"disputed\\\"\\n    SKIPPED = \\\"skipped\\\"\\n\\n\\nclass ClosureState(StrEnum):\\n    EMPTY = \\\"empty\\\"\\n    IN_PROGRESS = \\\"in_progress\\\"\\n    COMPLETED = \\\"completed\\\"\\n    FAILED = \\\"failed\\\"\\n    PARTIAL = \\\"partial\\\"\\n    UNKNOWN = \\\"unknown\\\"\\n\\n\\nclass ClosureExactRef(AipContractModel):\\n    resource_type: str = Field(min_length=1, max_length=120)\\n    resource_id: str = Field(min_length=1, max_length=240)\\n    revision: int = Field(ge=1)\\n    content_hash: str = Field(pattern=r\\\"^sha256:[0-9a-f]{64}$\\\")\\n    receipt_id: str = Field(min_length=1, max_length=240)\\n\\n\\nclass CompileThreeModuleClosureRequest(AipContractModel):\\n    module: ThreeModule\\n    source_ref: ClosureExactRef\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _source_type(self) -> \\\"CompileThreeModuleClosureRequest\\\":\\n        expected = {\\n            ThreeModule.CREATOR: \\\"CreatorBatchStartDecisionRevision\\\",\\n            ThreeModule.PRICE: \\\"PriceDispositionRevision\\\",\\n            ThreeModule.CUSTOMER: \\\"CustomerBatchStartDecisionRevision\\\",\\n        }\\n        if self.source_ref.resource_type != expected[self.module]:\\n            raise ValueError(\\\"three-module sourceRef type drifted\\\")\\n        return self\\n\\n\\nclass ThreeModuleItemOutcome(AipContractModel):\\n    item_key: str = Field(min_length=1, max_length=240)\\n    original_status: str = Field(min_length=1, max_length=80)\\n    canonical_outcome: CanonicalItemOutcome\\n    original_ref: ClosureExactRef\\n    receipt_ref: ClosureExactRef | None = None\\n\\n\\nclass ThreeModuleClosureLedger(AipContractModel):\\n    total: int = Field(ge=0)\\n    in_progress: int = Field(ge=0)\\n    succeeded: int = Field(ge=0)\\n    failed: int = Field(ge=0)\\n    unknown: int = Field(ge=0)\\n    disputed: int = Field(ge=0)\\n    skipped: int = Field(ge=0)\\n    state: ClosureState\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _conserved(self) -> \\\"ThreeModuleClosureLedger\\\":\\n        values = [self.in_progress, self.succeeded, self.failed, self.unknown, self.disputed, self.skipped]\\n        if self.total != sum(values):\\n            raise ValueError(\\\"three-module closure ledger must conserve items\\\")\\n        nonzero = sum(value > 0 for value in values)\\n        expected = (\\n            ClosureState.EMPTY if self.total == 0 else\\n            ClosureState.COMPLETED if self.succeeded == self.total else\\n            ClosureState.FAILED if self.failed == self.total else\\n            ClosureState.UNKNOWN if self.unknown == self.total else\\n            ClosureState.IN_PROGRESS if self.in_progress == self.total else\\n            ClosureState.PARTIAL if nonzero > 1 else\\n            ClosureState.PARTIAL\\n        )\\n        if self.state is not expected:\\n            raise ValueError(\\\"three-module closure state does not match item algebra\\\")\\n        return self\\n\\n\\nclass ThreeModuleClosureRevision(AipContractModel):\\n    tenant: TenantContext\\n    closure_id: str\\n    revision: int = 1\\n    module: ThreeModule\\n    source_ref: ClosureExactRef\\n    items: list[ThreeModuleItemOutcome] = Field(default_factory=list, max_length=2000)\\n    ledger: ThreeModuleClosureLedger\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    compiled_by: str\\n    compiled_at: datetime\\n\\n\\nclass BindThreeModuleUsageRequest(AipContractModel):\\n    closure_ref: ClosureExactRef\\n    usage_receipt_id: str = Field(min_length=1, max_length=240)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _closure(self) -> \\\"BindThreeModuleUsageRequest\\\":\\n        if self.closure_ref.resource_type != \\\"ThreeModuleClosureRevision\\\":\\n            raise ValueError(\\\"closureRef drifted\\\")\\n        return self\\n\\n\\nclass ThreeModuleUsageBindingRevision(AipContractModel):\\n    tenant: TenantContext\\n    binding_id: str\\n    revision: int = 1\\n    closure_ref: ClosureExactRef\\n    usage_receipt_ref: ClosureExactRef\\n    lineage_id: str\\n    quality: str = Field(pattern=r\\\"^(measured|estimated|unknown)$\\\")\\n    quantity: float | None = Field(default=None, ge=0)\\n    unit: str\\n    adjustment_total: float = 0\\n    settlement: str = Field(pattern=r\\\"^(measured|estimated|unknown)$\\\")\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    bound_at: datetime\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _unknown_has_no_quantity(self) -> \\\"ThreeModuleUsageBindingRevision\\\":\\n        if self.quality == \\\"unknown\\\" and self.quantity is not None:\\n            raise ValueError(\\\"unknown usage cannot invent zero or quantity\\\")\\n        if self.quality != \\\"unknown\\\" and self.quantity is None:\\n            raise ValueError(\\\"known usage requires canonical quantity\\\")\\n        return self\\n\\n\\nclass BindThreeModuleEffectRequest(AipContractModel):\\n    closure_ref: ClosureExactRef\\n    effect_review_id: str = Field(min_length=1, max_length=240)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _closure(self) -> \\\"BindThreeModuleEffectRequest\\\":\\n        if self.closure_ref.resource_type != \\\"ThreeModuleClosureRevision\\\":\\n            raise ValueError(\\\"closureRef drifted\\\")\\n        return self\\n\\n\\nclass ThreeModuleEffectBindingRevision(AipContractModel):\\n    tenant: TenantContext\\n    binding_id: str\\n    revision: int = 1\\n    closure_ref: ClosureExactRef\\n    effect_review_ref: ClosureExactRef\\n    maturity_status: str = Field(pattern=r\\\"^(immature|mature|insufficient|unknown)$\\\")\\n    accepted: bool\\n    effect_completed: bool\\n    sample_count: int = Field(ge=0)\\n    min_sample: int = Field(ge=1)\\n    cutoff_at: datetime\\n    observed_at: datetime\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    bound_at: datetime\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _maturity_is_honest(self) -> \\\"ThreeModuleEffectBindingRevision\\\":\\n        if self.effect_completed != (self.maturity_status == \\\"mature\\\"):\\n            raise ValueError(\\\"effectCompleted must follow canonical maturity only\\\")\\n        return self\\n\\n\\nclass BindThreeModuleHandoffRequest(AipContractModel):\\n    closure_ref: ClosureExactRef\\n    handoff_id: str = Field(min_length=1, max_length=240)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _closure(self) -> \\\"BindThreeModuleHandoffRequest\\\":\\n        if self.closure_ref.resource_type != \\\"ThreeModuleClosureRevision\\\":\\n            raise ValueError(\\\"closureRef drifted\\\")\\n        return self\\n\\n\\nclass ThreeModuleHandoffBindingRevision(AipContractModel):\\n    tenant: TenantContext\\n    binding_id: str\\n    revision: int = 1\\n    closure_ref: ClosureExactRef\\n    handoff_ref: ClosureExactRef\\n    transport_status: str\\n    business_decision: str | None = Field(default=None, pattern=r\\\"^(accepted|rejected|request_more|returned)$\\\")\\n    task_ref: dict[str, Any]\\n    task_run_ref: dict[str, Any]\\n    disclosure_ref_count: int = Field(ge=0)\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    bound_at: datetime\\n\\n\\nclass ThreeModuleClosureContributionView(AipContractModel):\\n    schema_version: str = THREE_MODULE_CLOSURE_SCHEMA_VERSION\\n    tenant: TenantContext\\n    module: ThreeModule\\n    evaluated_at: datetime\\n    atomic_skill_ids: list[str]\\n    logic_id: str\\n    primary_colleague: str\\n    collaborator_colleagues: list[str]\\n    latest_closure: ThreeModuleClosureRevision | None\\n    latest_usage: ThreeModuleUsageBindingRevision | None\\n    latest_effect: ThreeModuleEffectBindingRevision | None\\n    latest_handoff: ThreeModuleHandoffBindingRevision | None\\n    blockers: list[str]\\n    allowed_commands: list[str] = Field(default_factory=lambda: [\\n        \\\"COMPILE_THREE_MODULE_CLOSURE\\\",\\n        \\\"BIND_CANONICAL_USAGE\\\",\\n        \\\"BIND_CANONICAL_EFFECT_REVIEW\\\",\\n        \\\"BIND_CANONICAL_HANDOFF\\\",\\n    ])\\n    handoff_consume_allowed: bool = False\\n    memory_promotion_allowed: bool = False\\n    external_effects_allowed: bool = False\\n\\n\\n_CONTRIBUTION = {\\n    ThreeModule.CREATOR: (\\n        [\\\"creator-batch-prepare\\\", \\\"creator-lane-reconcile\\\", \\\"creator-relationship-review\\\"],\\n        \\\"ecommerce-creator-growth\\\",\\n        \\\"达人运营官\\\",\\n        [\\\"内容官\\\", \\\"数据参谋\\\"],\\n    ),\\n    ThreeModule.PRICE: (\\n        [\\\"compile-price-case\\\", \\\"prepare-price-handoff\\\", \\\"evaluate-price-effect\\\"],\\n        \\\"ecommerce-price-governance\\\",\\n        \\\"数据参谋\\\",\\n        [\\\"活动策划师\\\", \\\"导购顾问\\\"],\\n    ),\\n    ThreeModule.CUSTOMER: (\\n        [\\\"segment-customers\\\", \\\"design-customer-journey\\\", \\\"evaluate-dialogue-effect\\\"],\\n        \\\"ecommerce-customer-relationship\\\",\\n        \\\"私域管家\\\",\\n        [\\\"内容官\\\", \\\"客服专员\\\", \\\"导购顾问\\\", \\\"数据参谋\\\"],\\n    ),\\n}\\n\\n\\ndef _ledger(items: list[ThreeModuleItemOutcome]) -> ThreeModuleClosureLedger:\\n    counts = {value.value: 0 for value in CanonicalItemOutcome}\\n    for item in items:\\n        counts[item.canonical_outcome.value] += 1\\n    total = len(items)\\n    nonzero = sum(value > 0 for value in counts.values())\\n    state = (\\n        ClosureState.EMPTY if total == 0 else\\n        ClosureState.COMPLETED if counts[\\\"succeeded\\\"] == total else\\n        ClosureState.FAILED if counts[\\\"failed\\\"] == total else\\n        ClosureState.UNKNOWN if counts[\\\"unknown\\\"] == total else\\n        ClosureState.IN_PROGRESS if counts[\\\"in_progress\\\"] == total else\\n        ClosureState.PARTIAL if nonzero > 1 else\\n        ClosureState.PARTIAL\\n    )\\n    return ThreeModuleClosureLedger(total=total, state=state, **counts)\\n\\n\\nclass EcommerceWorkshopThreeModuleClosureService:\\n    def __init__(self, store: Any) -> None:\\n        self.store = store\\n\\n    @staticmethod\\n    def _tenant(scope: TenantScope) -> TenantContext:\\n        return TenantContext(org_id=scope.org_id, project_id=scope.project_id)\\n\\n    @staticmethod\\n    def _ref(resource_type: str, resource_id: str, content_hash: str) -> ClosureExactRef:\\n        return ClosureExactRef(\\n            resourceType=resource_type,\\n            resourceId=resource_id,\\n            revision=1,\\n            contentHash=f\\\"sha256:{content_hash}\\\",\\n            receiptId=f\\\"receipt-{resource_id}\\\",\\n        )\\n\\n    def compile(self, scope: TenantScope, request: CompileThreeModuleClosureRequest, actor: str, *, now: datetime | None = None) -> ThreeModuleClosureRevision:\\n        at = now or datetime.now(UTC)\\n        items = self.store.resolve_domain_items(scope, request.module, request.source_ref)\\n        payload = {\\\"module\\\": request.module, \\\"sourceRef\\\": request.source_ref, \\\"items\\\": items}\\n        content_hash = canonical_hash(payload)\\n        closure_id = f\\\"three-